function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var AN=[['Belief','Distribution beats implementation now.','[22:36]',false],['Model','Co-op, open source, about $3 a month.','[23:34]',false],['Market figure','$100 million a year, his number, unverified.','[28:54]',true]];
function kitNotes(host,lines){var w=document.createElement('div');w.className='notes-grid';w.innerHTML='<div class="note-panel"><div class="note-head"><h3>Campfire and music</h3><span class="note-src">His words, unverified</span></div><ul class="note-list">'+lines.map(function(l){return '<li'+(l[3]?' class="grain"':'')+'><span><b>'+kEsc(l[0])+'.</b> '+kEsc(l[1])+'</span><span class="note-ts">'+kEsc(l[2])+'</span></li>'}).join('')+'</ul></div>';host.appendChild(w);return w}
kitNotes(kSlot(),AN);
STATES.forEach(function(a,i){var b=document.createElement('div');b.style.maxWidth=a[1];kSlot(i).appendChild(b);kitNotes(b,a[0]?[AN[2]]:AN.slice(0,2))});
